void dfs1(int v, const vector<vector<int>>& adj, vector<bool>& visited, vector<int>& order) {
    visited[v] = true;
    for (int u : adj[v]) {
        if (!visited[u]) {
            dfs1(u, adj, visited, order);
        }
    }
    order.push_back(v);
}

void dfs2(int v, const vector<vector<int>>& adj_rev, vector<bool>& visited, vector<int>& component) {
    visited[v] = true;
    component.push_back(v);
    for (int u : adj_rev[v]) {
        if (!visited[u]) {
            dfs2(u, adj_rev, visited, component);
        }
    }
}

vector<vector<int>> sccs(const vector<vector<int>>& adj) {
    int n = adj.size();
    vector<bool> visited(n, false);
    vector<int> order;
    order.reserve(n);
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            dfs1(i, adj, visited, order);
        }
    }

    vector<vector<int>> adj_rev(n);
    for (int i = 0; i < n; i++) {
        for (int u : adj[i]) {
            adj_rev[u].push_back(i);
        }
    }

    fill(visited.begin(), visited.end(), false);
    reverse(order.begin(), order.end());

    vector<vector<int>> components;
    for (int v : order) {
        if (!visited[v]) {
            vector<int> comp;
            dfs2(v, adj_rev, visited, comp);
            components.push_back(comp);
        }
    }
    return components;
}

void solve() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<int>> adj(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        adj[u].push_back(v);
    }
    debug(adj);
    vector<vector<int>> scc_ = sccs(adj);
    vector<int> color(n);
    for(int i = 0; i < scc_.size(); i++) {
        for(int j = 0; j < scc_[i].size(); j++) {
            color[scc_[i][j]] = i;
        }
    }
    debug(color);
    while(k--) {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        debug(color[u], color[v]);
        if(color[u] == color[v]) {
            cout << "YES\n";
        } else {
            cout << "NO\n";
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t = 1;
    while (t--) {
        solve();
    }
}
